const cache = new Map<number, string>();

function assembleAvif(val8: number): string {
  const cached = cache.get(val8);
  if (cached) return cached;
  const template = b64ToBytes(TEMPLATES[GROUPS[val8]]);
  const av1 = hexToBytes(AV1[val8]);
  const result = new Uint8Array(template.length + av1.length);
  result.set(template, 0);
  result.set(av1, template.length);
  const url = "data:image/avif;base64," + bytesToB64(result);
  cache.set(val8, url);
  return url;
}

export function getHdrAvif(nits: number): string {
  const pq = nitsToPQ(Math.max(0, Math.min(10000, nits)));
  const val8 = Math.min(255, Math.max(0, Math.round(pq * 255)));
  return assembleAvif(val8);
}
